import { ReferralAvailabilityRead } from "@/types/emr/referral/referral";
import { UserReadMinimal } from "@/types/user/user";

export type BecknFlow = "referral" | "appointment";

export type BecknAdapter = "bap" | "bpp";

/**
 * Lifecycle of a plugin transaction: `QUEUED` until ONIX acknowledges the
 * request, then the uppercase action (e.g. `SELECT`) and `ON_<ACTION>` once
 * the callback is stored. `NACK` / `ERROR` carry `last_error`.
 */
export type BecknTransactionStatus = string;

export interface BecknLastError {
  code?: string;
  message?: string;
  [key: string]: unknown;
}

export interface BecknTransactionList {
  id: string;
  transaction_id: string;
  adapter: BecknAdapter;
  flow: BecknFlow;
  status: BecknTransactionStatus;
  network_id: string;
  counterparty_id: string;
  counterparty_uri: string;
  contract_id: string;
  coordination_id: string;
  last_error: BecknLastError | null;
  created_date: string | null;
  modified_date: string | null;
}

export interface BecknRouting {
  bap_id?: string;
  bap_uri?: string;
  bpp_id?: string;
  bpp_uri?: string;
}

export interface BecknTransactionRetrieve extends BecknTransactionList {
  routing: BecknRouting;
  context: Record<string, unknown>;
  actions: string[];
  patient: string | null;
  facility: string | null;
  created_by: UserReadMinimal | null;
}

export interface ReferralTransactionRetrieve extends BecknTransactionRetrieve {
  /** The origin Care referral; `transaction_id` equals it for Care-created referrals. */
  referral_id: string | null;
  confirm: Record<string, unknown> | null;
}

export interface BecknMessage {
  id: number;
  transaction_id: string | null;
  message_id: string;
  action: string;
  direction: string;
  delivery_status: string;
  processing_status: string;
  attempts: number;
  last_error: string;
  payload: {
    context?: Record<string, unknown>;
    message?: Record<string, unknown>;
    error?: Record<string, unknown>;
  };
  ack: Record<string, unknown> | null;
  reply_to: number | null;
  created_date: string | null;
  modified_date: string | null;
}

/** Context overrides; the plugin validates all five routing keys as required. */
export interface BecknContextOverride {
  network_id: string;
  bap_id: string;
  bap_uri: string;
  bpp_id: string;
  bpp_uri: string;
  version?: string;
  ttl?: string;
  schema_context?: string[];
}

interface BecknActionBody {
  context?: BecknContextOverride;
  message?: Record<string, unknown>;
}

export interface BecknDiscoverBody extends BecknActionBody {
  health_service_type?: string;
  acceptance_mode?: string;
  text_search?: string;
  filters?: Record<string, unknown>;
}

export interface ReferralSelectBody extends BecknActionBody {
  offer_id: string;
}

/** The plugin maps `patient_care` to a consultation and anything else to a lab referral. */
export type ReferralNetworkCategory = "patient_care" | "other";

/**
 * `facility` is the origin Care facility the plugin creates the referral from.
 * `encounter` links the origin referral to that encounter; it stays in Care and
 * is never sent over the network.
 */
export interface ReferralConfirmBody extends BecknActionBody {
  facility: string;
  patient?: string;
  patient_name?: string;
  encounter?: string;
  title?: string;
  reason?: string;
  category?: ReferralNetworkCategory;
  offer_id?: string;
  assigned_facility_id?: string;
  emergency?: boolean;
  priority?: number;
}

export interface BecknActionResponse {
  transaction_id: string;
  message_id: string;
  action: string;
  status: BecknTransactionStatus;
}

export interface BecknCatalogs {
  transaction_id: string;
  catalogs: Record<string, unknown>[];
}

export type ReferralUrgency = "routine" | "urgent" | "emergency";

export const REFERRAL_URGENCIES: ReferralUrgency[] = [
  "routine",
  "urgent",
  "emergency",
];

/** One provider offer flattened from an `on_discover` catalog. */
export interface NetworkOffer {
  key: string;
  transactionId: string;
  offerId: string;
  offerName?: string;
  providerId?: string;
  providerName?: string;
  catalogName?: string;
  context: BecknContextOverride;
}

export function isNetworkAvailability(
  availability?: Pick<ReferralAvailabilityRead, "entity_type"> | null,
) {
  return availability?.entity_type === "external";
}

export function isFailedTransaction(status?: string) {
  return status === "NACK" || status === "ERROR";
}

/** Gateway errors can carry whole HTML bodies; keep user-facing text short. */
export function transactionErrorText(
  lastError?: BecknLastError | null,
  maxLength = 200,
) {
  const text = lastError?.message ?? lastError?.code;
  if (!text) return undefined;
  return text.length > maxLength ? `${text.slice(0, maxLength)}…` : text;
}

/** A request is in flight until its `ON_<ACTION>` callback or a failure. */
export function isAwaitingCallback(status?: string) {
  return !!status && !status.startsWith("ON_") && !isFailedTransaction(status);
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function asString(value: unknown): string | undefined {
  return typeof value === "string" && value ? value : undefined;
}

function descriptorName(value: unknown): string | undefined {
  return asString(asRecord(asRecord(value)?.descriptor)?.name);
}

/**
 * Flattens every stored `on_discover` callback into selectable offers. A
 * discover can be answered by several BPPs, so each offer keeps the routing of
 * the envelope (or catalog) it came from for the follow-up `select`/`confirm`.
 */
export function extractNetworkOffers(messages: BecknMessage[]): NetworkOffer[] {
  const offers: NetworkOffer[] = [];
  messages.forEach((message, messageIndex) => {
    const context = asRecord(message.payload.context) ?? {};
    const catalogs = asArray(asRecord(message.payload.message)?.catalogs);
    catalogs.forEach((rawCatalog, catalogIndex) => {
      const catalog = asRecord(rawCatalog);
      if (!catalog) return;
      const provider = asRecord(catalog.provider);
      const routing: BecknContextOverride = {
        network_id: asString(context.networkId) ?? "",
        bap_id: asString(context.bapId) ?? "",
        bap_uri: asString(context.bapUri) ?? "",
        bpp_id: asString(catalog.bppId) ?? asString(context.bppId) ?? "",
        bpp_uri: asString(catalog.bppUri) ?? asString(context.bppUri) ?? "",
      };
      asArray(catalog.offers).forEach((rawOffer, offerIndex) => {
        const offerId = asString(asRecord(rawOffer)?.id);
        if (!offerId) return;
        offers.push({
          key: `${messageIndex}-${catalogIndex}-${offerIndex}`,
          transactionId: message.transaction_id ?? "",
          offerId,
          offerName: descriptorName(rawOffer),
          providerId: asString(provider?.id),
          providerName: descriptorName(provider) ?? descriptorName(catalog),
          catalogName: descriptorName(catalog),
          context: routing,
        });
      });
    });
  });
  return offers;
}

export function networkOfferLabel(offer: NetworkOffer) {
  return (
    [offer.providerName, offer.offerName].filter(Boolean).join(" — ") ||
    offer.catalogName ||
    offer.offerId
  );
}

import { useMutation, useQuery } from "@tanstack/react-query";
import { Network, RefreshCw } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { BecknTransactionStatusBadge } from "@/components/Referral/network/BecknTransactionStatusBadge";
import { NETWORK_POLL_INTERVAL_MS } from "@/components/Referral/network/networkReferral";
import { useIsNetworkReferral } from "@/components/Referral/network/ReferralNetworkBadge";

import {
  isAwaitingCallback,
  isFailedTransaction,
  ReferralTransactionRetrieve,
} from "@/types/ccn/ccn";
import { ccnReferralApi } from "@/types/ccn/ccnApi";
import { ReferralRead } from "@/types/emr/referral/referral";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";
import { formatDateTime } from "@/Utils/utils";

/**
 * Network transaction of a network referral. Referrals raised in Care on a
 * network availability use the referral id as `transaction_id`; referrals
 * created through the discover flow are opened with an explicit `transactionId`.
 */
export function ReferralNetworkStatus({
  referral,
  transactionId = referral.id,
}: {
  referral: ReferralRead;
  transactionId?: string;
}) {
  const { t } = useTranslation();
  const isNetwork = useIsNetworkReferral(referral.availability);
  const transactionQuery = useQuery<ReferralTransactionRetrieve>({
    queryKey: ["ccn", "referral", "transaction", transactionId],
    queryFn: query(ccnReferralApi.get, {
      pathParams: { transactionId },
      silent: true,
    }),
    enabled: isNetwork,
    retry: false,
    refetchInterval: (q) =>
      isAwaitingCallback(q.state.data?.status)
        ? NETWORK_POLL_INTERVAL_MS
        : false,
  });
  const statusMutation = useMutation({
    mutationFn: mutate(ccnReferralApi.status, {
      pathParams: { transactionId },
    }),
    onSuccess: () => transactionQuery.refetch(),
  });
  if (!isNetwork) return null;
  const transaction = transactionQuery.data;
  const notLinked =
    transactionQuery.error instanceof HTTPError &&
    transactionQuery.error.status === 404;

  return (
    <section
      aria-label={t("ccn_network_status")}
      className="space-y-3 rounded-lg border border-border bg-background p-4"
      data-cy="referral-network-status"
    >
      <div className="flex items-center justify-between gap-2">
        <h2 className="flex items-center gap-2 text-sm font-semibold">
          <Network className="size-4" aria-hidden="true" />
          {t("ccn_network_status")}
        </h2>
        {transaction && (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            disabled={
              statusMutation.isPending || isAwaitingCallback(transaction.status)
            }
            onClick={() => statusMutation.mutate({})}
          >
            <RefreshCw
              aria-hidden="true"
              className={
                statusMutation.isPending ? "size-4 animate-spin" : "size-4"
              }
            />
            {t("ccn_request_status")}
          </Button>
        )}
      </div>
      {transactionQuery.isLoading && (
        <p role="status" className="text-sm text-muted-foreground">
          {t("loading")}
        </p>
      )}
      {notLinked && (
        <p className="text-sm text-muted-foreground">
          {t("ccn_transaction_not_linked")}
        </p>
      )}
      {transactionQuery.isError && !notLinked && (
        <p role="alert" className="text-sm text-destructive">
          {t("ccn_network_unavailable")}
        </p>
      )}
      {transaction && (
        <dl className="grid gap-2 text-sm">
          <div>
            <dt className="text-muted-foreground">{t("status")}</dt>
            <dd className="mt-1">
              <BecknTransactionStatusBadge status={transaction.status} />
            </dd>
          </div>
          {isFailedTransaction(transaction.status) &&
            transaction.last_error && (
              <div role="alert">
                <dt className="text-muted-foreground">{t("ccn_last_error")}</dt>
                <dd className="mt-1 line-clamp-4 break-all text-destructive">
                  {transaction.last_error.message ??
                    transaction.last_error.code}
                </dd>
              </div>
            )}
          {transaction.counterparty_id && (
            <div>
              <dt className="text-muted-foreground">{t("ccn_counterparty")}</dt>
              <dd className="mt-1 break-all">{transaction.counterparty_id}</dd>
            </div>
          )}
          {transaction.contract_id && (
            <div>
              <dt className="text-muted-foreground">{t("ccn_contract_id")}</dt>
              <dd className="mt-1 break-all font-mono text-xs">
                {transaction.contract_id}
              </dd>
            </div>
          )}
          {transaction.actions.length > 0 && (
            <div>
              <dt className="text-muted-foreground">
                {t("ccn_network_activity")}
              </dt>
              <dd className="mt-1 break-words font-mono text-xs">
                {transaction.actions.join(" → ")}
              </dd>
            </div>
          )}
          {transaction.modified_date && (
            <div>
              <dt className="text-muted-foreground">{t("last_modified")}</dt>
              <dd className="mt-1">
                {formatDateTime(transaction.modified_date)}
              </dd>
            </div>
          )}
        </dl>
      )}
    </section>
  );
}

import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { isAwaitingCallback, isFailedTransaction } from "@/types/ccn/ccn";

function statusGroup(status: string) {
  if (isFailedTransaction(status)) return "failed";
  if (status === "QUEUED") return "queued";
  if (status === "ON_CONFIRM") return "confirmed";
  if (isAwaitingCallback(status)) return "awaiting";
  return "responded";
}

const VARIANTS = {
  failed: "destructive",
  queued: "neutral",
  awaiting: "warning",
  confirmed: "success",
  responded: "info",
} as const;

export function BecknTransactionStatusBadge({ status }: { status: string }) {
  const { t } = useTranslation();
  const group = statusGroup(status);
  return (
    <Badge variant={VARIANTS[group]} size="sm" dot title={status}>
      {t(`ccn_transaction_status__${group}`)}
      <span className="font-mono text-[0.65rem] opacity-70">{status}</span>
    </Badge>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Network } from "lucide-react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";

import { isNetworkAvailability } from "@/types/ccn/ccn";
import { referralAvailabilityApi } from "@/types/emr/referral/referralApi";
import query from "@/Utils/request/query";

/**
 * Referral list and detail payloads only carry the availability id, so the
 * availability is fetched once per id (shared cache) to tell network referrals apart.
 */
export function useIsNetworkReferral(availabilityId?: string) {
  const { data } = useQuery({
    queryKey: ["referral-availability", availabilityId],
    queryFn: query(referralAvailabilityApi.get, {
      pathParams: { availabilityId: availabilityId ?? "" },
      silent: true,
    }),
    enabled: !!availabilityId,
    staleTime: 5 * 60 * 1000,
    retry: false,
  });
  return isNetworkAvailability(data);
}

export function ReferralNetworkBadge({
  availabilityId,
}: {
  availabilityId: string;
}) {
  const { t } = useTranslation();
  const isNetwork = useIsNetworkReferral(availabilityId);
  if (!isNetwork) return null;
  return (
    <Badge variant="info" size="sm" data-cy="referral-network-badge">
      <Network className="size-3" aria-hidden="true" />
      {t("ccn_network")}
    </Badge>
  );
}

import {
  isFailedTransaction,
  NetworkOffer,
  ReferralNetworkCategory,
  ReferralTransactionRetrieve,
  ReferralUrgency,
  transactionErrorText,
} from "@/types/ccn/ccn";
import { ccnReferralApi } from "@/types/ccn/ccnApi";
import { ReferralType } from "@/types/emr/referral/referral";
import { callApi } from "@/Utils/request/query";
import { sleep } from "@/Utils/utils";

export const NETWORK_POLL_INTERVAL_MS = 1500;
const CALLBACK_TIMEOUT_MS = 90_000;

export const HEALTH_SERVICE_TYPE_FOR_REFERRAL: Record<ReferralType, string> = {
  consultation: "PHYSICAL_CONSULTATION",
  lab: "LAB_TEST",
};

const CATEGORY_FOR_REFERRAL: Record<ReferralType, ReferralNetworkCategory> = {
  consultation: "patient_care",
  lab: "other",
};

/** Beckn urgency is `emergency` or a priority; the plugin treats >= 2 as urgent. */
const URGENCY_PRIORITY: Record<ReferralUrgency, number> = {
  routine: 1,
  urgent: 2,
  emergency: 3,
};

export class NetworkTransactionError extends Error {
  constructor(
    readonly reason: "failed" | "timeout",
    readonly transaction?: ReferralTransactionRetrieve,
  ) {
    super(reason);
  }
}

/** Polls the transaction until the `on_<action>` callback for it is stored. */
async function waitForCallback(
  transactionId: string,
  action: string,
  signal?: AbortSignal,
): Promise<ReferralTransactionRetrieve> {
  const expected = `ON_${action.toUpperCase()}`;
  const deadline = Date.now() + CALLBACK_TIMEOUT_MS;
  for (;;) {
    signal?.throwIfAborted();
    const transaction = await callApi(ccnReferralApi.get, {
      pathParams: { transactionId },
      silent: true,
      signal,
    });
    if (transaction.status === expected) return transaction;
    if (isFailedTransaction(transaction.status)) {
      throw new NetworkTransactionError("failed", transaction);
    }
    if (Date.now() > deadline) {
      throw new NetworkTransactionError("timeout", transaction);
    }
    await sleep(NETWORK_POLL_INTERVAL_MS);
  }
}

export interface NetworkReferralRequest {
  offer: NetworkOffer;
  facilityId: string;
  patientId: string;
  encounterId?: string;
  title: string;
  reason: string;
  referralType: ReferralType;
  urgency: ReferralUrgency;
}

export type NetworkReferralStep = "select" | "confirm";

/**
 * Sends a referral over the network: `select` the discovered offer, then
 * `confirm` it. The plugin creates the origin Care referral when the
 * coordinator activates the contract and exposes it as `referral_id`.
 */
export async function submitNetworkReferral(
  request: NetworkReferralRequest,
  onStep: (step: NetworkReferralStep) => void,
  signal?: AbortSignal,
): Promise<ReferralTransactionRetrieve> {
  const { offer } = request;
  const transactionId = offer.transactionId;

  onStep("select");
  await callApi(ccnReferralApi.select, {
    pathParams: { transactionId },
    body: { offer_id: offer.offerId, context: offer.context },
    signal,
  });
  await waitForCallback(transactionId, "select", signal);

  onStep("confirm");
  await callApi(ccnReferralApi.confirm, {
    pathParams: { transactionId },
    body: {
      facility: request.facilityId,
      patient: request.patientId,
      ...(request.encounterId ? { encounter: request.encounterId } : {}),
      title: request.title,
      reason: request.reason || undefined,
      category: CATEGORY_FOR_REFERRAL[request.referralType],
      offer_id: offer.offerId,
      assigned_facility_id: offer.providerId,
      emergency: request.urgency === "emergency",
      priority: URGENCY_PRIORITY[request.urgency],
    },
    signal,
  });
  return waitForCallback(transactionId, "confirm", signal);
}

export function networkErrorDetail(error: unknown): string | undefined {
  if (!(error instanceof NetworkTransactionError)) return undefined;
  return transactionErrorText(error.transaction?.last_error);
}

